// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import {IERC20} from "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import {SafeERC20} from "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import {ReentrancyGuard} from "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/// @title PayrollOS
/// @notice Multi-tenant payroll system where each wallet manages its own isolated company payroll.
/// @dev Salaries are expected in USDC base units.
contract PayrollOS is ReentrancyGuard {
    using SafeERC20 for IERC20;

    // =============================================================
    //                           Errors
    // =============================================================

    error ZeroAddress();
    error ZeroAmount();
    error AlreadyRegistered();
    error EmployeeNotFound();
    error InvalidBatchRange();
    error BatchTooLarge();
    error PayrollRunInProgress();
    error PeriodMismatch();

    // =============================================================
    //                           Types
    // =============================================================

    struct Employee {
        address wallet;
        uint256 salaryNet;
        string name;
        bool active;
    }

    struct EmployeeRecord {
        Employee data;
        uint256 index;
        bool exists;
    }

    struct PayrollRunData {
        uint256 runId;
        string period;
        uint256 totalAmount;
        uint256 employeeCount;
        uint256 timestamp;
        PayrollStatus status;
    }

    enum PayrollStatus {
        Completed
    }

    struct PayrollRunProgress {
        uint256 runId;
        bytes32 periodHash;
        uint256 nextIndex;
        uint256 totalAmount;
        uint256 employeeCount;
        uint256 timestamp;
        bool inProgress;
    }

    // =============================================================
    //                       State Variables
    // =============================================================

    IERC20 public immutable usdc;

    uint256 public constant MAX_BATCH_SIZE = 50;

    /// @dev Employee wallet list per company.
    mapping(address => address[]) private _employeeWallets;

    /// @dev Employee records per company and employee wallet.
    mapping(address => mapping(address => EmployeeRecord)) private _employees;

    /// @dev Payroll run history per company and run ID.
    mapping(address => mapping(uint256 => PayrollRunData)) private _payrollRuns;

    /// @dev Number of payroll runs per company.
    mapping(address => uint256) private _runCount;

    /// @dev Total disbursed USDC per company.
    mapping(address => uint256) private _totalDisbursed;

    /// @dev In-progress payroll state per company.
    mapping(address => PayrollRunProgress) private _payrollRunProgress;

    // =============================================================
    //                            Events
    // =============================================================

    event EmployeeRegistered(address indexed company, address indexed wallet, uint256 salaryNet, string name);
    event EmployeeUpdated(address indexed company, address indexed wallet, uint256 salaryNet, string name, bool active);
    event EmployeeRemoved(address indexed company, address indexed wallet);
    event PayrollRun(
        address indexed company,
        uint256 indexed runId,
        string period,
        uint256 totalAmount,
        uint256 employeeCount,
        uint256 timestamp
    );
    event SalaryPaid(address indexed company, uint256 indexed runId, address indexed wallet, uint256 amount, string employeeName);
    event SalaryFailed(address indexed company, uint256 indexed runId, address indexed wallet, string reason);

    // =============================================================
    //                         Constructor
    // =============================================================

    /// @param usdcToken USDC token contract address.
    constructor(address usdcToken) {
        if (usdcToken == address(0)) revert ZeroAddress();
        usdc = IERC20(usdcToken);
    }

    // =============================================================
    //                      Employee Management
    // =============================================================

    /// @notice Registers an employee for the caller's company.
    function registerEmployee(address wallet, uint256 salaryNet, string calldata name, bool active) external {
        if (wallet == address(0)) revert ZeroAddress();
        if (salaryNet == 0) revert ZeroAmount();

        address company = msg.sender;
        if (_employees[company][wallet].exists) revert AlreadyRegistered();

        uint256 index = _employeeWallets[company].length;
        _employeeWallets[company].push(wallet);

        _employees[company][wallet] = EmployeeRecord({
            data: Employee({wallet: wallet, salaryNet: salaryNet, name: name, active: active}),
            index: index,
            exists: true
        });

        emit EmployeeRegistered(company, wallet, salaryNet, name);
    }

    /// @notice Updates an existing employee for the caller's company.
    function updateEmployee(address wallet, uint256 salaryNet, string calldata name, bool active) external {
        if (wallet == address(0)) revert ZeroAddress();
        if (salaryNet == 0) revert ZeroAmount();

        address company = msg.sender;
        EmployeeRecord storage record = _employees[company][wallet];
        if (!record.exists) revert EmployeeNotFound();

        record.data.salaryNet = salaryNet;
        record.data.name = name;
        record.data.active = active;

        emit EmployeeUpdated(company, wallet, salaryNet, name, active);
    }

    /// @notice Removes an employee from the caller's company via swap-and-pop.
    function removeEmployee(address wallet) external {
        address company = msg.sender;
        EmployeeRecord storage record = _employees[company][wallet];
        if (!record.exists) revert EmployeeNotFound();

        uint256 indexToRemove = record.index;
        uint256 lastIndex = _employeeWallets[company].length - 1;

        if (indexToRemove != lastIndex) {
            address lastWallet = _employeeWallets[company][lastIndex];
            _employeeWallets[company][indexToRemove] = lastWallet;
            _employees[company][lastWallet].index = indexToRemove;
        }

        _employeeWallets[company].pop();
        delete _employees[company][wallet];

        emit EmployeeRemoved(company, wallet);
    }

    // =============================================================
    //                       Payroll Execution
    // =============================================================

    /// @notice Runs a payroll batch for the caller's company.
    /// @dev Caller must approve this contract on USDC before execution.
    /// @param period Label for this payroll cycle (e.g. "2026-09").
    /// @param startIndex Start index (inclusive) over company employee list.
    /// @param endIndex End index (exclusive) over company employee list.
    function runPayroll(string calldata period, uint256 startIndex, uint256 endIndex) external nonReentrant {
        address company = msg.sender;
        uint256 len = _employeeWallets[company].length;
        bytes32 periodHash = keccak256(bytes(period));

        PayrollRunProgress storage progress = _payrollRunProgress[company];

        if (progress.inProgress) {
            if (progress.periodHash != periodHash) revert PeriodMismatch();

            if (startIndex == 0 && endIndex == 0) {
                startIndex = progress.nextIndex;
                endIndex = startIndex + MAX_BATCH_SIZE;
                if (endIndex > len) endIndex = len;
            } else {
                if (startIndex != progress.nextIndex) revert InvalidBatchRange();
                if (endIndex <= startIndex || endIndex > len) revert InvalidBatchRange();
                if (endIndex - startIndex > MAX_BATCH_SIZE) revert BatchTooLarge();
            }
        } else {
            if (startIndex == 0 && endIndex == 0) {
                startIndex = 0;
                endIndex = len > MAX_BATCH_SIZE ? MAX_BATCH_SIZE : len;
            } else {
                if (startIndex != 0) revert PayrollRunInProgress();
                if (endIndex <= startIndex || endIndex > len) revert InvalidBatchRange();
                if (endIndex - startIndex > MAX_BATCH_SIZE) revert BatchTooLarge();
            }

            uint256 runId = _runCount[company] + 1;
            progress.runId = runId;
            progress.periodHash = periodHash;
            progress.nextIndex = startIndex;
            progress.totalAmount = 0;
            progress.employeeCount = 0;
            progress.timestamp = block.timestamp;
            progress.inProgress = true;
        }

        uint256 runIdInProgress = progress.runId;

        for (uint256 i = startIndex; i < endIndex; ++i) {
            Employee storage employeeData = _employees[company][_employeeWallets[company][i]].data;
            if (!employeeData.active) continue;

            try this._safeTransferFrom(company, employeeData.wallet, employeeData.salaryNet) {
                progress.totalAmount += employeeData.salaryNet;
                unchecked {
                    ++progress.employeeCount;
                }
                emit SalaryPaid(company, runIdInProgress, employeeData.wallet, employeeData.salaryNet, employeeData.name);
            } catch Error(string memory reason) {
                emit SalaryFailed(company, runIdInProgress, employeeData.wallet, reason);
            } catch (bytes memory lowLevelData) {
                emit SalaryFailed(company, runIdInProgress, employeeData.wallet, _decodeRevertReason(lowLevelData));
            }
        }

        progress.nextIndex = endIndex;

        if (endIndex == len) {
            uint256 finalRunId = progress.runId;
            uint256 totalAmount = progress.totalAmount;
            uint256 paidEmployeeCount = progress.employeeCount;
            uint256 timestamp = progress.timestamp;

            _payrollRuns[company][finalRunId] = PayrollRunData({
                runId: finalRunId,
                period: period,
                totalAmount: totalAmount,
                employeeCount: paidEmployeeCount,
                timestamp: timestamp,
                status: PayrollStatus.Completed
            });

            _runCount[company] = finalRunId;
            _totalDisbursed[company] += totalAmount;

            emit PayrollRun(company, finalRunId, period, totalAmount, paidEmployeeCount, timestamp);

            delete _payrollRunProgress[company];
        }
    }

    // =============================================================
    //                         Read Methods
    // =============================================================

    /// @notice Returns all registered employees for a company.
    /// @dev Data is visible only to the company itself.
    function getEmployees(address company) external view returns (Employee[] memory employees_) {
        if (company != msg.sender) revert EmployeeNotFound();

        uint256 len = _employeeWallets[company].length;
        employees_ = new Employee[](len);

        for (uint256 i = 0; i < len; ++i) {
            employees_[i] = _employees[company][_employeeWallets[company][i]].data;
        }
    }

    /// @notice Returns an employee record by wallet for a company.
    /// @dev Data is visible only to the company itself.
    function getEmployee(address company, address wallet) external view returns (Employee memory) {
        if (company != msg.sender) revert EmployeeNotFound();

        EmployeeRecord storage record = _employees[company][wallet];
        if (!record.exists) revert EmployeeNotFound();

        return record.data;
    }

    /// @notice Returns payroll run data for a company and run ID.
    /// @dev Data is visible only to the company itself.
    function getPayrollRun(address company, uint256 runId) external view returns (PayrollRunData memory) {
        if (company != msg.sender) revert EmployeeNotFound();
        return _payrollRuns[company][runId];
    }

    /// @notice Returns number of payroll runs executed by a company.
    /// @dev Data is visible only to the company itself.
    function getRunCount(address company) external view returns (uint256) {
        if (company != msg.sender) revert EmployeeNotFound();
        return _runCount[company];
    }

    /// @notice Returns cumulative USDC disbursed by a company.
    /// @dev Data is visible only to the company itself.
    function getTotalDisbursed(address company) external view returns (uint256) {
        if (company != msg.sender) revert EmployeeNotFound();
        return _totalDisbursed[company];
    }

    /// @notice Returns count of active employees for a company.
    /// @dev Data is visible only to the company itself.
    function getActiveEmployeeCount(address company) external view returns (uint256 count) {
        if (company != msg.sender) revert EmployeeNotFound();

        uint256 len = _employeeWallets[company].length;
        for (uint256 i = 0; i < len; ++i) {
            if (_employees[company][_employeeWallets[company][i]].data.active) {
                unchecked {
                    ++count;
                }
            }
        }
    }

    // =============================================================
    //                      Internal Utilities
    // =============================================================

    /// @notice Performs a SafeERC20 transferFrom in a context catchable by try/catch.
    /// @dev Restricted to self-calls so arbitrary users cannot invoke this directly.
    function _safeTransferFrom(address from, address to, uint256 amount) external {
        require(msg.sender == address(this), "PayrollOS: only self");
        usdc.safeTransferFrom(from, to, amount);
    }

    /// @dev Best-effort decode of low-level revert data into a human-readable reason.
    function _decodeRevertReason(bytes memory revertData) internal pure returns (string memory) {
        if (revertData.length < 68) {
            return "transfer failed";
        }

        assembly {
            revertData := add(revertData, 0x04)
        }

        return abi.decode(revertData, (string));
    }
}

